/* the reference filter vocabulary: 32px, radius 8, 12px bold, recessed fill,
   lit top edge, darker bottom inset. */

.chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: var(--chip-height, var(--control-h-sm));
  padding: 0 calc(12px * var(--density));
  border: 0;
  border-radius: var(--chip-radius, var(--r-sm));
  background: var(--recess-fill);
  box-shadow: var(--shadow-recess);
  font-family: var(--font-body);
  font-size: var(--text-caption);
  font-weight: 700;
  color: var(--ink-muted);
  white-space: nowrap;
  transition:
    background-color var(--dur) var(--ease),
    color var(--dur) var(--ease);
}

.chip:hover:not(:disabled) {
  background: var(--recess-fill-hover);
  color: var(--ink-body);
}

.chip:active:not(:disabled) {
  box-shadow: inset 0 1px 2px rgba(var(--rgb-contact), 0.14), inset 0 -1px 0 rgba(var(--rgb-white), 0.6);
}

.active,
.active:hover:not(:disabled) {
  background: var(--chip-active-fill);
  color: var(--brand-deep);
  font-weight: 700;
  box-shadow: var(--chip-active-shadow);
}

.active:hover:not(:disabled) {
  background: var(--chip-active-fill-hover);
}

.chip:focus-visible {
  outline: none;
  box-shadow: var(--shadow-recess), var(--focus-ring);
}

.chip:disabled {
  cursor: not-allowed;
  color: var(--ink-disabled);
}

.icon {
  display: inline-flex;
  opacity: 0.75;
}

.count {
  min-width: 18px;
  padding: 1px 5px;
  border-radius: var(--r-full);
  background: rgba(var(--rgb-white), 0.7);
  font-size: 10.5px;
  font-variant-numeric: tabular-nums;
  text-align: center;
}

/* ── Search chip ─────────────────────────────────────────────────────── */

.search {
  position: relative;
  display: inline-flex;
  align-items: center;
  height: var(--chip-height, var(--control-h-sm));
  border-radius: var(--chip-radius, var(--r-sm));
  background: var(--recess-fill);
  box-shadow: var(--shadow-recess);
  color: var(--ink-muted);
  transition:
    background-color var(--dur) var(--ease),
    box-shadow var(--dur) var(--ease);
}

/* Fills the filter row; never narrower than a readable placeholder. */
.grow {
  flex: 1 1 240px;
  min-width: min(100%, 200px);
}

.search:hover {
  background: var(--recess-fill-hover);
}

.search.active {
  background: var(--wash-active);
  color: var(--ink-brand);
}

/* The one filter control with a caret gets a heavier focus ring. */
.search:focus-within {
  box-shadow: var(--shadow-recess), 0 0 0 1px transparent, 0 0 0 3px rgba(var(--rgb-brand), 0.5);
}

.searchIcon {
  position: absolute;
  left: 10px;
  pointer-events: none;
}

.searchInput {
  width: 100%;
  height: 100%;
  padding: 0 28px 0 29px;
  border: 0;
  outline: none;
  background: transparent;
  font-size: var(--text-caption);
  font-weight: 700;
  color: inherit;
}

/* The chip draws focus (.search:focus-within). (0,2,0) drops globals.css's
   :focus-visible outline in any load order. */
.searchInput:focus-visible {
  outline: none;
}

.searchInput::placeholder {
  color: var(--ink-muted);
  opacity: 1;
}

.searchInput::-webkit-search-cancel-button {
  display: none;
}

.clear {
  position: absolute;
  right: 6px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border: 0;
  border-radius: var(--r-2xs);
  background: transparent;
  color: inherit;
  opacity: 0.7;
}

.clear:hover {
  opacity: 1;
  background: rgba(var(--rgb-white), 0.6);
}

.clear:focus-visible {
  outline: none;
  opacity: 1;
  box-shadow: 0 0 0 2px var(--focus-color);
}

"use client";

import { useRef, type ComponentPropsWithRef, type ReactNode } from "react";
import { cx } from "../_internal/cx";
import { IconSearch, IconX } from "../Icon/Icon";
import styles from "./FilterChip.module.css";

export type FilterChipProps = Omit<ComponentPropsWithRef<"button">, "children"> & {
  /** Filter applied. Shown by tint and ink only, never a ring. */
  active?: boolean;
  icon?: ReactNode;
  count?: number;
  children: ReactNode;
};

/**
 * A filter bar is navigation, not data entry, so its controls are recessed
 * chips rather than outlined boxes. Toggle semantics via aria-pressed.
 */
export function FilterChip({ active = false, icon, count, children, className, type = "button", ...rest }: FilterChipProps) {
  return (
    <button data-slot="filter-chip" type={type} aria-pressed={active} className={cx(styles.chip, active && styles.active, className)} {...rest}>
      {icon ? <span className={styles.icon}>{icon}</span> : null}
      <span>{children}</span>
      {count !== undefined ? <span className={styles.count}>{count}</span> : null}
    </button>
  );
}

export type FilterSearchProps = {
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  "aria-label": string;
  className?: string;
  /** Width of the chip. Defaults to 220px. Ignored when grow is set. */
  width?: number | string;
  /**
   * Fill the row: the search takes every pixel the other filters leave
   * (FilterBar's pattern, where dropdowns sit at the end).
   */
  grow?: boolean;
};

/**
 * Live search chip. Enter blurs (filtering is already live, and it must not
 * submit an enclosing form); Escape clears. Icon and text share one tone.
 */
export function FilterSearch({
  value,
  onChange,
  placeholder = "Search",
  "aria-label": ariaLabel,
  className,
  width = 220,
  grow,
}: FilterSearchProps) {
  const ref = useRef<HTMLInputElement>(null);
  return (
    <div data-slot="filter-search" className={cx(styles.search, grow && styles.grow, value && styles.active, className)} style={grow ? undefined : { width }}>
      <IconSearch size={13} className={styles.searchIcon} />
      <input
        ref={ref}
        type="search"
        value={value}
        placeholder={placeholder}
        aria-label={ariaLabel}
        className={styles.searchInput}
        onChange={(e) => onChange(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === "Enter") {
            e.preventDefault();
            ref.current?.blur();
          } else if (e.key === "Escape" && value) {
            e.preventDefault();
            e.stopPropagation();
            onChange("");
          }
        }}
      />
      {value ? (
        <button
          type="button"
          className={styles.clear}
          aria-label="Clear search"
          onClick={() => {
            onChange("");
            ref.current?.focus();
          }}
        >
          <IconX size={12} />
        </button>
      ) : null}
    </div>
  );
}
